def investigate(context, acquire):
    history = acquire("history")
    if not history:
        return {"value": None, "unresolved": True}

    def simulate(actions, put_mode, channel_mode, trigger):
        main = {}
        other = {}
        main_changes = 0
        main_total = 0
        other_total = 0
        log = []
        in_tx = False
        tx_conn = None
        tx_snapshot = None

        def apply_put(conn, key, value):
            nonlocal main_changes, main_total, other_total
            if conn == "main":
                if put_mode == "ignore":
                    if key not in main:
                        main[key] = value
                        main_changes = 1
                        main_total += 1
                        if trigger:
                            log.append((key, value))
                    else:
                        main_changes = 0
                elif put_mode == "replace":
                    main[key] = value
                    main_changes = 1
                    main_total += 1
                    if trigger:
                        log.append((key, value))
                else:
                    if key in main:
                        main[key] = value
                    else:
                        main[key] = value
                    main_changes = 1
                    main_total += 1
                    if trigger:
                        log.append((key, value))
            else:
                if put_mode == "ignore":
                    if key not in other:
                        other[key] = value
                        other_total += 1
                        if trigger:
                            log.append((key, value))
                elif put_mode == "replace":
                    other[key] = value
                    other_total += 1
                    if trigger:
                        log.append((key, value))
                else:
                    other[key] = value
                    other_total += 1
                    if trigger:
                        log.append((key, value))

        def apply_update(conn, key, value):
            nonlocal main_changes, main_total, other_total
            if conn == "main":
                if key in main:
                    main[key] = value
                    main_changes = 1
                    main_total += 1
                else:
                    main_changes = 0
            else:
                if key in other:
                    other[key] = value
                    other_total += 1

        def apply_delete(conn, key):
            nonlocal main_changes, main_total, other_total
            if conn == "main":
                if key in main:
                    del main[key]
                    main_changes = 1
                    main_total += 1
                else:
                    main_changes = 0
            else:
                if key in other:
                    del other[key]
                    other_total += 1

        for action in actions:
            op = action.get("op")
            conn = action.get("connection", "main")
            if op == "begin":
                in_tx = True
                tx_conn = conn
                if conn == "main":
                    tx_snapshot = dict(main)
                else:
                    tx_snapshot = dict(other)
            elif op == "commit":
                in_tx = False
                tx_conn = None
                tx_snapshot = None
            elif op == "rollback":
                if tx_conn == "main":
                    main.clear()
                    main.update(tx_snapshot)
                else:
                    other.clear()
                    other.update(tx_snapshot)
                in_tx = False
                tx_conn = None
                tx_snapshot = None
                if conn == "main":
                    main_changes = 0
            elif op == "put":
                apply_put(conn, action.get("key"), action.get("value"))
            elif op == "update":
                apply_update(conn, action.get("key"), action.get("value"))
            elif op == "delete":
                apply_delete(conn, action.get("key"))

        if channel_mode == "changes":
            channel = main_changes
        elif channel_mode == "total_main":
            channel = main_total
        else:
            channel = main_total + other_total
        committed = dict(main)
        committed.update(other)
        return channel, len(committed), sum(committed.values())

    candidates = []
    for put_mode in ("ignore", "replace", "upsert"):
        for channel_mode in ("changes", "total_main", "total_both"):
            for trigger in (False, True):
                ok = True
                for receipt in history:
                    actions = receipt.get("actions", [])
                    observed = receipt.get("observed", {})
                    ch, cnt, sm = simulate(actions, put_mode, channel_mode, trigger)
                    if ch != observed.get("channel") or cnt != observed.get("committed_count") or sm != observed.get("committed_sum"):
                        ok = False
                        break
                if ok:
                    candidates.append((put_mode, channel_mode, trigger))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    values = []
    for put_mode, channel_mode, trigger in candidates:
        ch, cnt, sm = simulate(actions, put_mode, channel_mode, trigger)
        if goal == "channel":
            values.append(ch)
        elif goal == "committed_count":
            values.append(cnt)
        elif goal == "committed_sum":
            values.append(sm)
        else:
            return {"value": None, "unresolved": True}

    if len(set(values)) == 1:
        return {"value": values[0], "unresolved": False}
    return {"value": None, "unresolved": True}
